namespace Revestik.Api.Services.Projects.Documents;

// Storage keys are opaque, generated by the storage provider, never user supplied.
public interface IProjectFileStorage
{
    Task<string> SaveAsync(Stream source, CancellationToken cancellationToken);
    Task<Stream> OpenReadAsync(string storageKey, CancellationToken cancellationToken);
    Task DeleteAsync(string storageKey, CancellationToken cancellationToken);
}
